  check(`[...document.querySelectorAll('${context} [data-amp-composer-context-item]')].every(e => e.scrollWidth <= e.clientWidth)`, 'model and runner are not truncated when the toolbar has room');
  check(`document.querySelector('${context} [data-amp-composer-context-item="runner"]').title === 'Runner: tiru5-macbook-pro\\nDirectory: /Users/tiru5/My Repo/app' && document.querySelector('${context} [data-amp-composer-context-item="model"]').title === 'Model: claude-opus-5-5\\nMode: high'`, 'runner directory and mode are available on hover');
