  check(`document.querySelectorAll('[data-amp-composer-context]').length === 1 && (${contextText}) === 'claude-opus-5-5 | tiru5-macbook-pro'`, 'context follows Amp re-rendering the upload trigger without duplicating');
  check(`fixtureThreadRequests.at(-1).id === 'fixture-a' && fixtureThreadRequests.at(-1).credentials === 'same-origin'`, 'thread data is requested same-origin for the open thread');
  browser('eval', `fixtureAgents.navigate('fixture-b')`);
  browser('wait', '--fn', `(${contextText}).includes('Orb')`);
  check(`(${contextText}) === 'medium | Orb' && document.querySelector('${context} [data-amp-composer-context-item="runner"]').title === 'Executor: Orb'`, 'orb threads without replies show their mode and orb executor');
  browser('eval', `fixtureAgents.navigate('fixture-mode-effort')`);
  browser('wait', '--fn', `(${contextText}).includes('low effort')`);
  check(`(${contextText}) === 'medium | low effort | Orb'`, 'mode fallback shows configured effort once without confusing mode and effort');
  browser('eval', `fixtureAgents.navigate('fixture-c')`);
  browser('wait', '--fn', `(${contextText}).includes('build-box')`);
  check(`(${contextText}) === 'claude-sonnet-5-5 | xhigh effort | build-box' && document.querySelector('${context} [data-amp-composer-context-item="model"]').title === 'Model: claude-sonnet-5-5\\nMode: external-agent:claude-code, xhigh effort'`, 'local external agents show the selected model, configured effort, and runner hostname');
  check(`document.querySelector('${context} [data-amp-composer-context-item="runner"]').title === 'Runner: build-box\\nDirectory: /srv/my work'`, 'file URI working directories display as paths');
  browser('eval', `fixtureAgents.navigate('fixture-orb-external')`);
  browser('wait', '--fn', `(${contextText}).includes('claude-opus-5-5')`);
  check(`(${contextText}) === 'claude-opus-5-5 | high effort | Orb' && document.querySelector('${context} [data-amp-composer-context-item="runner"]').title === 'Executor: Orb'`, 'external agents running in orbs show their selected model, configured effort, and Orb');
  check(`[...document.querySelectorAll('${context} [data-amp-composer-context-item]')].every(e => e.scrollWidth <= e.clientWidth)`, 'model, effort, and executor fit without truncation at desktop width');
  browser('eval', `fixtureAgents.navigate('fixture-orb-unknown')`);
  browser('wait', '--fn', `fixtureThreadRequests.at(-1).id === 'fixture-orb-unknown' && (${contextText}).includes('Model unavailable')`);
  check(`(${contextText}) === 'Model unavailable | medium effort | Orb' && !document.querySelector('${context} [data-amp-composer-context-item="model"]')`, 'configured effort remains visible even when the model is unavailable');
  check(`document.querySelector('${context} [data-amp-composer-context-item="mode"]').title === 'Mode: external-agent:claude-code, medium effort'`, 'unknown external model retains its agent mode in the tooltip');
  browser('eval', `fixtureAgents.navigate('fixture-missing')`);
  browser('wait', '--fn', `fixtureThreadRequests.at(-1).id === 'fixture-missing'`);
  browser('wait', '--fn', `!document.querySelector('${context}')`);
  check(`!document.querySelector('[data-amp-composer-context]')`, 'failed thread data never shows the previous thread context');
  browser('eval', `fixtureAgents.navigate('fixture-a')`);
  browser('wait', '--fn', `(${contextText}).includes('tiru5-macbook-pro')`);
  const requests = evaluate('fixtureThreadRequests.length');
  browser('eval', `document.querySelector('#fixture-transcript').append(document.createElement('p'))`);
  browser('wait', '500');
  check(`fixtureThreadRequests.length === ${requests}`, 'transcript updates within a minute reuse the loaded context');
  browser('eval', 'chrome.storage.local.set({ showComposerContext: false, infoOrb: false })');
  browser('wait', '--fn', `!document.querySelector('[data-amp-composer-context]')`);
  browser('eval', `fixtureAgents.navigate('fixture-b')`);
  browser('wait', '500');
  check(`!document.querySelector('[data-amp-composer-context]') && fixtureThreadRequests.length === ${requests}`, 'turning the setting off removes the line and stops thread data requests');
  browser('eval', 'chrome.storage.local.set({ showComposerContext: true, infoOrb: true })');
  browser('wait', '--fn', `(${contextText}).includes('Orb')`);
  check(`(${contextText}) === 'medium | Orb'`, 'turning the setting back on restores the line');
